#!/bin/bash
cd unlearning && source .venv/bin/activate
bash solution/jureca_grid.sh "r3" "--method td --blocks 12 --bs-f 64 --bs-r 64 --eval-every 100 --n-eval 3500 --n-eval-r 1000 --steps 2500 --alpha 10 --lr 5e-5 --target medium --w-stat 0.3" "--method td --blocks 12 --bs-f 64 --bs-r 64 --eval-every 100 --n-eval 3500 --n-eval-r 1000 --steps 2500 --alpha 10 --lr 1e-4 --target strong --w-stat 0.1" "--method td --blocks 12 --bs-f 64 --bs-r 64 --eval-every 100 --n-eval 3500 --n-eval-r 1000 --steps 2500 --alpha 10 --lr 5e-5 --target mixcls --select cls --w-stat 0.1" "--method td --blocks 12 --bs-f 64 --bs-r 64 --eval-every 100 --n-eval 3500 --n-eval-r 1000 --steps 2500 --alpha 10 --lr 5e-5 --target mix --select strong --w-stat 0.2"
cd solution && for r in ../output/runs/r3_g*/; do [ -f $r/best.pt ] && python make_submission.py $r/best.pt ../output/sub_$(basename $r).pt; done; cd .. && python solution/collect.py
